name":"occurred_at","type":"timestamp with time zone","default":"now()","identity":"","not_null":true,"generated":""}],"indexes":[{"name":"commercial_events_order_idx","definition":"CREATE INDEX commercial_events_order_idx ON public.commercial_events USING btree (order_id, occurred_at)","constraint_owned":false},{"name":"commercial_events_pkey","definition":"CREATE UNIQUE INDEX commercial_events_pkey ON public.commercial_events USING btree (id)","constraint_owned":true},{"name":"commercial_events_source_external_event_id_key","definition":"CREATE UNIQUE INDEX commercial_events_source_external_event_id_key ON public.commercial_events USING btree (source, external_event_id)","constraint_owned":true}],"policies":null,"triggers":null,"force_rls":false,"constraints":[{"name":"commercial_events_actor_profile_id_fkey","type":"f","validated":true,"definition":"FOREIGN KEY (actor_profile_id) REFERENCES profiles(id) ON DELETE SET NULL"},{"name":"commercial_events_order_id_fkey","type":"f","validated":true,"definition":"FOREIGN KEY (order_id) REFERENCES commercial_orders(id) ON DELETE RESTRICT"},{"name":"commercial_events_pkey","type":"p","validated":true,"definition":"PRIMARY KEY (id)"},{"name":"commercial_events_source_check","type":"c","validated":true,"definition":"CHECK ((source = ANY (ARRAY[''operator''::text, ''asaas''::text, ''signature_provider''::text])))"},{"name":"commercial_events_source_external_event_id_key","type":"u","validated":true,"definition":"UNIQUE (source, external_event_id)"}]},{"acl":"{authenticated=r/postgres,postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres}","rls":true,"name":"commercial_order_units","owner":"postgres","columns":[{"acl":null,"name":"id","type":"uuid","default":"gen_random_uuid()","identity":"","not_null":true,"generated":""},{"acl":null,"name":"order_id","type":"uuid","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"ordinal","type":"integer","default":null,"identity":"","not_null":true,"gener